new="""let stationAmbience=null,stationAmbienceRoom='';function startStationAmbience(){try{if(!stationAmbience){const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C(),master=ctx.createGain(),low=ctx.createOscillator(),mid=ctx.createOscillator(),filter=ctx.createBiquadFilter(),noise=ctx.createBufferSource(),noiseFilter=ctx.createBiquadFilter(),noiseGain=ctx.createGain(),lfo=ctx.createOscillator(),lfoGain=ctx.createGain();master.gain.value=0;low.type='sine';low.frequency.value=49;mid.type='triangle';mid.frequency.value=73;filter.type='lowpass';filter.frequency.value=170;low.connect(filter);mid.connect(filter);filter.connect(master);const buffer=ctx.createBuffer(1,ctx.sampleRate*3,ctx.sampleRate),data=buffer.getChannelData(0);let seed=0x51A7;for(let i=0;i<data.length;i++){seed=(seed*1664525+1013904223)>>>0;data[i]=((seed/4294967296)*2-1)*.65;}noise.buffer=buffer;noise.loop=true;noiseFilter.type='lowpass';noiseFilter.frequency.value=260;noise.connect(noiseFilter);noiseFilter.connect(noiseGain);noiseGain.gain.value=.055;lfo.frequency.value=.075;lfoGain.gain.value=.018;lfo.connect(lfoGain);lfoGain.connect(master.gain);noiseGain.connect(master);master.connect(ctx.destination);low.start();mid.start();noise.start();lfo.start();stationAmbience={ctx,master,filter,noiseFilter,noiseGain,low,mid,noise};}const a=stationAmbience;if(a.ctx.state==='suspended')a.ctx.resume().catch(()=>{});const prefs=audioSettings?.master??55;a.master.gain.setTargetAtTime(prefs<=0?0:.11*(prefs/100),a.ctx.currentTime,.7);const id=roomId||'A';if(id!==stationAmbienceRoom){stationAmbienceRoom=id;const outside='KLMNOP'.includes(id),technical='DEF'.includes(id),archive='GHIJ'.includes(id);a.filter.frequency.setTargetAtTime(outside?360:technical?115:archive?210:170,a.ctx.currentTime,1.2);a.noiseFilter.frequency.setTargetAtTime(outside?620:technical?150:archive?330:260,a.ctx.currentTime,1.2);a.low.frequency.setTargetAtTime(outside?37:technical?53:49,a.ctx.currentTime,1.2);a.mid.frequency.setTargetAtTime(archive?91:outside?61:73,a.ctx.currentTime,1.2);}}catch(e){console.debug('Атмосферный звук недоступен',e);}}function pauseStationAmbience(){if(stationAmbience?.ctx.state==='running')stationAmbience.ctx.suspend().catch(()=>{});}function closeSystem(){sessionPaused=false;startStationAmbience();for(const c of directorChannels.values())"""
